class TestFindRelevantContextDecay:
    def test_falls_back_to_match_count_when_surreal_down(self, compound):
        """When SurrealDB is unavailable, results still come back sorted."""
        compound.vault.search.return_value = [
            {"path": "decisions/foo.md", "snippet": "x"},
            {"path": "decisions/foo.md", "snippet": "y"},
            {"path": "patterns/bar.md", "snippet": "z"},
        ]

        with patch.object(compound, "_fetch_neuron_metadata_batch", return_value={}):
            with patch.object(compound, "_track_access"):
                results = compound.find_relevant_context("test query")

        assert len(results) == 2
        # foo.md has 2 matches → higher relevance_score than bar.md
        assert results[0]["path"] == "decisions/foo.md"
        assert results[0]["match_count"] == 2

    def test_metadata_boosts_frequently_accessed_doc(self, compound):
        """A document with high access_count ranks above a stale one with same matches."""
        compound.vault.search.return_value = [
            {"path": "decisions/new.md", "snippet": "hit"},
            {"path": "decisions/old.md", "snippet": "hit"},
        ]

        now = datetime.now(timezone.utc)
        metadata = {
            "decisions/new.md": {
                "path": "decisions/new.md",
                "last_accessed": now.isoformat(),
                "access_count": 50,
            },
            "decisions/old.md": {
                "path": "decisions/old.md",
                "last_accessed": (now - timedelta(days=200)).isoformat(),
                "access_count": 0,
            },
        }

        with patch.object(compound, "_fetch_neuron_metadata_batch", return_value=metadata):
            with patch.object(compound, "_track_access"):
                results = compound.find_relevant_context("test")

        assert results[0]["path"] == "decisions/new.md"

    def test_relevance_score_added_to_each_result(self, compound):
        compound.vault.search.return_value = [
            {"path": "patterns/foo.md", "snippet": "match"}
        ]

        with patch.object(compound, "_fetch_neuron_metadata_batch", return_value={}):
            with patch.object(compound, "_track_access"):
                results = compound.find_relevant_context("foo")

        assert "relevance_score" in results[0]
        assert results[0]["relevance_score"] > 0

    def test_empty_results_no_crash(self, compound):
        compound.vault.search.return_value = []

        with patch.object(compound, "_fetch_neuron_metadata_batch", return_value={}):
            with patch.object(compound, "_track_access"):
                results = compound.find_relevant_context("nothing")

        assert results == []

    def test_track_access_called_with_top_paths(self, compound):
        compound.vault.search.return_value = [
            {"path": "decisions/a.md", "snippet": "hit"}
        ]

        with patch.object(compound, "_fetch_neuron_metadata_batch", return_value={}):
            with patch.object(compound, "_track_access") as mock_track:
                compound.find_relevant_context("test")

        mock_track.assert_called_once_with(["decisions/a.md"])


